f=APP/'web/app.js';s=f.read_text().replace('Uniform smoothing around the entire join, with a soft boundary.', 'Extra geometric smoothing around the full join; base seam cleanup is always applied.').replace('Negative: concave / recessed. Positive: convex / raised.', 'Recess or raise the full attachment circumference. Negative: concave. Positive: convex.').replace("'Overall scale','%','Scales the entire fitting region.'", "'Overall anatomy scale','%','Scales the anatomy; the surrounding pelvis keeps its shape.'");f.write_text(s)
